<template>
  <header class="sw-header" :class="{ 'admin-header': isAdmin }">
    <button class="menu-button" type="button" aria-label="Open menu" @click="menuOpen = !menuOpen">☰</button>
    <router-link :to="isAdmin ? '/admin' : '/'" class="brand" @click="menuOpen = false"><span class="brand-mark">🤝</span><span class="brand-name">STOCK<span>WELL</span></span></router-link>
    <nav v-if="!isAdmin" class="desktop-nav"><router-link to="/">Home</router-link><router-link to="/catalogue">Catalogue</router-link><router-link v-if="isLoggedIn" to="/member-dashboard">Group Hub</router-link><router-link v-if="isLoggedIn" to="/proposals">Group Decisions</router-link><router-link v-if="isLoggedIn" to="/order-history">Order History</router-link><router-link v-if="isLoggedIn" to="/addresses">Addresses</router-link><router-link v-if="isLoggedIn" to="/suggestions">Suggestions</router-link></nav>
    <nav v-else class="desktop-nav"><router-link to="/admin">Dashboard</router-link><router-link to="/admin/management">Management</router-link><router-link to="/admin/suggestions">Suggestions</router-link></nav>
    <div class="header-actions">
      <template v-if="isLoggedIn && isAdmin"><span class="admin-badge">ADMIN</span><router-link class="icon-button" to="/admin/profile" aria-label="Admin Profile">👤</router-link><button class="icon-button" type="button" @click="toggleTheme">{{ isDark ? '☀' : '☾' }}</button><button class="logout-btn" type="button" @click="logout">Logout</button></template>
      <template v-else-if="isLoggedIn"><router-link class="icon-button" to="/cart" aria-label="Cart">🛒<span v-if="cartCount" class="cart-count">{{ cartCount }}</span></router-link><router-link class="icon-button" to="/profile" aria-label="Profile">👤</router-link><button class="icon-button" type="button" @click="toggleTheme">{{ isDark ? '☀' : '☾' }}</button><button class="logout-btn" type="button" @click="logout">Logout</button></template>
      <template v-else><router-link class="join-btn" to="/login-signup">Join</router-link><button class="icon-button" type="button" @click="toggleTheme">{{ isDark ? '☀' : '☾' }}</button></template>
    </div>
  </header>
  <nav v-if="menuOpen" class="mobile-nav" :class="{ 'admin-mobile-nav': isAdmin }">
    <template v-if="isAdmin"><router-link to="/admin" @click="menuOpen = false">Admin Dashboard</router-link><router-link to="/admin/management" @click="menuOpen = false">Management</router-link><router-link to="/admin/suggestions" @click="menuOpen = false">Suggestions</router-link><router-link to="/admin/profile" @click="menuOpen = false">Profile</router-link><button type="button" @click="toggleTheme">{{ isDark ? '☀ Light mode' : '☾ Dark mode' }}</button><button type="button" @click="logout">Logout</button></template>
    <template v-else><router-link to="/" @click="menuOpen = false">Home</router-link><router-link to="/catalogue" @click="menuOpen = false">Catalogue</router-link><router-link v-if="isLoggedIn" to="/cart" @click="menuOpen = false">Cart</router-link><router-link v-if="isLoggedIn" to="/member-dashboard" @click="menuOpen = false">Group Hub</router-link><router-link v-if="isLoggedIn" to="/proposals" @click="menuOpen = false">Group Decisions</router-link><router-link v-if="isLoggedIn" to="/order-history" @click="menuOpen = false">Order History</router-link><router-link v-if="isLoggedIn" to="/addresses" @click="menuOpen = false">My Addresses</router-link><router-link v-if="isLoggedIn" to="/suggestions" @click="menuOpen = false">Suggestions</router-link><router-link v-if="isLoggedIn" to="/profile" @click="menuOpen = false">Profile</router-link><router-link v-if="!isLoggedIn" to="/login-signup" @click="menuOpen = false">Join</router-link><button type="button" @click="toggleTheme">{{ isDark ? '☀ Light mode' : '☾ Dark mode' }}</button><button v-if="isLoggedIn" type="button" @click="logout">Logout</button></template>
  </nav>
</template>
<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { useRouter } from 'vue-router';
import { useTheme } from '../../composables/useTheme.js';
import { readCartState } from '../../composables/useCartState.js';
const router=useRouter(); const {isDark,toggleTheme}=useTheme(); const menuOpen=ref(false); const cartCount=ref(readCartState().itemCount||0); const authVersion=ref(0);
const hasSession=computed(()=>{authVersion.value;return Boolean(localStorage.getItem('token')||localStorage.getItem('sw_token'))});
const isLoggedIn=computed(()=>hasSession.value);
const isAdmin=computed(()=>{authVersion.value;try{return hasSession.value && JSON.parse(localStorage.getItem('user')||'null')?.role==='admin'}catch{return false}});
function refreshAuthState(){authVersion.value+=1} function updateCart(e){cartCount.value=Number(e.detail?.itemCount??e.detail??0)} function refreshCart(){cartCount.value=Number(readCartState().itemCount||0)}
function logout(){['token','sw_token','user','stokvel','stockwellCheckoutState','stockwellCartState','basketCount'].forEach(k=>localStorage.removeItem(k));cartCount.value=0;menuOpen.value=false;refreshAuthState();router.push('/')}
function handleStorage(){refreshAuthState();refreshCart()}
onMounted(()=>{window.addEventListener('cart-state-updated',updateCart);window.addEventListener('basket-updated',updateCart);window.addEventListener('auth-updated',refreshAuthState);window.addEventListener('login-completed',refreshAuthState);window.addEventListener('storage',handleStorage);window.addEventListener('focus',handleStorage)})
onBeforeUnmount(()=>{window.removeEventListener('cart-state-updated',updateCart);window.removeEventListener('basket-updated',updateCart);window.removeEventListener('auth-updated',refreshAuthState);window.removeEventListener('login-completed',refreshAuthState);window.removeEventListener('storage',handleStorage);window.removeEventListener('focus',handleStorage)})
</script>
<style scoped>
.sw-header{position:sticky;top:0;z-index:1000;min-height:68px;padding:0 28px;display:flex;align-items:center;gap:28px;background:color-mix(in srgb,var(--sw-page-background) 94%,transparent);border-bottom:1px solid var(--sw-input-border);backdrop-filter:blur(16px);color:var(--sw-page-text);transition:.25s}.admin-header{background:color-mix(in srgb,var(--sw-purple-900) 95%,transparent);border-bottom-color:rgba(200,176,25,.28)}.brand{display:flex;align-items:center;gap:10px;min-width:160px;color:var(--sw-page-text);text-decoration:none}.admin-header .brand{color:#fff}.brand-mark{width:42px;height:42px;border-radius:50%;background:var(--sw-gold-500);color:var(--sw-purple-900);display:grid;place-items:center;font-size:22px;border:2px solid var(--sw-gold-500)}.brand-name{font-size:20px;font-weight:800;letter-spacing:.06em}.brand-name span{color:var(--sw-gold-500)}.desktop-nav{flex:1;display:flex;justify-content:center;gap:18px}.desktop-nav a{color:var(--sw-page-text-soft);font-size:10px;letter-spacing:.08em;text-transform:uppercase;text-decoration:none}.admin-header .desktop-nav a{color:rgba(255,255,255,.72)}.desktop-nav a:hover,.desktop-nav a.router-link-active{color:var(--sw-gold-500)}.header-actions{display:flex;align-items:center;gap:9px}.icon-button{position:relative;width:38px;height:38px;display:grid;place-items:center;color:var(--sw-page-text);text-decoration:none;border:1px solid transparent;border-radius:50%;background:transparent;cursor:pointer;font-size:17px}.admin-header .icon-button{color:#fff}.icon-button:hover{color:var(--sw-gold-500);background:var(--sw-page-surface);border-color:var(--sw-input-border)}.cart-count{position:absolute;top:-2px;right:-2px;min-width:17px;height:17px;padding:0 4px;display:grid;place-items:center;border-radius:50%;background:var(--sw-orange-600);color:#fff;font:700 9px var(--sw-font-body)}.admin-badge{padding:6px 9px;border-radius:999px;color:var(--sw-gold-500);border:1px solid rgba(200,176,25,.45);background:rgba(200,176,25,.1);font:700 9px var(--sw-font-body);letter-spacing:.12em}.join-btn,.logout-btn{padding:9px 15px;border:1px solid var(--sw-input-border);border-radius:999px;background:var(--sw-page-surface);color:var(--sw-page-text);font:11px var(--sw-font-body);text-decoration:none;cursor:pointer}.admin-header .logout-btn{background:rgba(255,255,255,.08);color:#fff;border-color:rgba(255,255,255,.18)}.join-btn:hover,.logout-btn:hover{background:var(--sw-gold-500);border-color:var(--sw-gold-500);color:var(--sw-purple-900)}.menu-button,.mobile-nav{display:none}@media(max-width:1050px){.desktop-nav{gap:10px}.desktop-nav a{font-size:9px}}@media(max-width:900px){.sw-header{padding:0 16px;gap:12px}.brand{min-width:auto}.brand-mark{width:36px;height:36px;font-size:19px}.brand-name{font-size:17px}.desktop-nav{display:none}.menu-button{display:block;padding:6px;background:transparent;color:var(--sw-page-text);font-size:21px;cursor:pointer}.admin-header .menu-button{color:#fff}.header-actions{margin-left:auto;gap:3px}.join-btn,.logout-btn,.admin-badge{display:none}.mobile-nav{display:flex;flex-direction:column;position:sticky;top:68px;z-index:999;background:var(--sw-page-background);border-bottom:1px solid var(--sw-input-border)}.admin-mobile-nav{background:var(--sw-purple-900);border-bottom-color:rgba(255,255,255,.12)}.mobile-nav a,.mobile-nav button{padding:14px 20px;border:0;border-bottom:1px solid var(--sw-input-border);background:transparent;color:var(--sw-page-text);text-align:left;text-decoration:none;font:11px var(--sw-font-body);text-transform:uppercase;cursor:pointer}.admin-mobile-nav a,.admin-mobile-nav button{color:#fff;border-bottom-color:rgba(255,255,255,.1)}.admin-mobile-nav a.router-link-active{color:var(--sw-gold-500)}}
</style>
